userscript.function:

if (Sepoa.request.status) {
    filterObj.setValue('SMR_STATUS', Sepoa.request.status);
}

var headerText = "";
if (Sepoa.request["docType"] && Sepoa.request["docType"] == "D") {
    headerText = Sepoa.cache.text.get("SLM_280.LAYOUT_A_HEADER_D");
    filterObj.setHide("F_FILTER");
    gridObj.setColumnHidden(gridObj.getColIndexById('RE_FLAG'), true);
    gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_USE_TYPE'), true);
} else {
    headerText = Sepoa.cache.text.get("SLM_280.LAYOUT_A_HEADER");
}
callFunction(['p', 'p'], "setHeaderText", [headerText]);

if (Sepoa.info.MASTER_COMPANY_FLAG != 'Y') {
	filterObj.setHide("AFFILIATED_COMPANY");
}

doQuery();


var smrNumber = "";
var applyType = "";
gridObj.editStop();

if (rowId) {
    var selectedRow = rowId;
} else {
    var selectedRows = gridObj.getGridChangedRows("SELECTED");
    if (selectedRows.length < 1) {
        Alert(Sepoa.cache.text.get('MESSAGE.1004'));
        return;
    }

    if (selectedRows.length > 1) {
        Alert(Sepoa.cache.text.get('SLM_201.MESSAGE_SELECT_ONE_REQ'));
        return;
    }
    var selectedRow = selectedRows[0];
}


var status = gridObj.cells(selectedRow, gridObj.getColIndexById("SMR_STATUS")).getValue();
if (status == 'T') {
    Alert(Sepoa.cache.text.get('SLM_201.MESSAGE_NOT_TEMP_SEARCH'));
    return;
}
smrNumber = gridObj.cells(selectedRow, gridObj.getColIndexById("SMR_NUMBER")).getValue();
applyType = gridObj.cells(selectedRow, gridObj.getColIndexById("APPLY_TYPE")).getValue();
companyCode = gridObj.cells(selectedRow, gridObj.getColIndexById("COMPANY_CODE")).getValue();
if (smrNumber != '') {
    var mode = 'VIEW';
    callFunction('p', 'changeMode', [applyType, smrNumber, mode, companyCode]);
}


var selectedRows = gridObj.getGridChangedRows("SELECTED");
var smrNumber = "";
var applyType = "";
gridObj.editStop();

if (selectedRows.length < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004'));
    return;
}

if (selectedRows.length > 1) {
    Alert(Sepoa.cache.text.get('SLM_201.MESSAGE_SELECT_ONE_REQ'));
    return;
}

var selectedRow = selectedRows[0];
var addUserId = gridObj.cells(selectedRow, gridObj.getColIndexById("ADD_USER_ID")).getValue();
if(Sepoa.info.ID != addUserId){
	Alert(Sepoa.cache.text.get('SLM_201.MSG_0008'));
    return;
}

var status = gridObj.cells(selectedRow, gridObj.getColIndexById("SMR_STATUS")).getValue();
if (['T', 'R', 'N', 'F'].indexOf(status) == -1) { // 임시저장, 반려
    Alert(Sepoa.cache.text.get('SLM_201.MESSAGE_NOT_TEMP_UPDATE'));
    return;
}
smrNumber = gridObj.cells(selectedRow, gridObj.getColIndexById("SMR_NUMBER")).getValue();
applyType = gridObj.cells(selectedRow, gridObj.getColIndexById("APPLY_TYPE")).getValue();

var mode = 'EDITOR';
callFunction('p', 'changeMode', [applyType, smrNumber, mode]);


var selectedRow = gridObj.getGridChangedRows("SELECTED");
var smrNumber = "";
var applyType = "";
gridObj.editStop();

if (selectedRow.length < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004'));
    return;
}

for (var i in selectedRow) {
    var status = gridObj.cells(selectedRow[i], gridObj.getColIndexById("SMR_STATUS")).getValue();
    var addUserId = gridObj.cells(selectedRow[i], gridObj.getColIndexById("ADD_USER_ID")).getValue();
    if (status != 'T') {
        Alert(Sepoa.cache.text.get('SLM_201.MESSAGE_NOT_TEMP_DELETE'));
        return;
    }
    if(Sepoa.info.ID != addUserId){
    	Alert(Sepoa.cache.text.get('SLM_201.MSG_0008'));
        return;
    }
}

if (gridObj.getGridChangedRows("SELECTED").length > 0 && Confirm(Sepoa.cache.text.get('MESSAGE.1015'), function(result) {
        if (result) {
            gridObj.editStop();
            gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doSave', 'PROCESS_ID=sepoa.svc.seal.SepoaReqSealService', 'METHOD=doDeleteRequestInfo'], 'SELECTED');

        }
    }));


gridObj.editStop();
var selectedRow = gridObj.getGridChangedRows("SELECTED");
var allowedStatusArr = ['W', 'G', 'I'];

if (selectedRow.length < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004'));
    return;
}

const adminProfileCode = Sepoa.config.get('sepoa.system.manager.profile.code');

for (var i in selectedRow) {
    var status = gridObj.cells(selectedRow[i], gridObj.getColIndexById("SMR_STATUS")).getValue();
    var addUserId = gridObj.cells(selectedRow[i], gridObj.getColIndexById("ADD_USER_ID")).getValue();

    if (allowedStatusArr.indexOf(status) == -1 || [Sepoa.info.ID, adminProfileCode].indexOf(addUserId) == -1) {
        Alert(Sepoa.cache.text.get('SLM_201.CANT_WITHDRAW')); // 회수할 수 없는 건입니다.
        return;
    }
}

if (Confirm(Sepoa.cache.text.get('MESSAGE.0029'), function(result) {
        if (result) {
            gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doSave', 'PROCESS_ID=sepoa.svc.seal.SepoaReqSealService', 'METHOD=doWithdrawRequest'], 'SELECTED');
        }
    }));


if (comboName == 'SMR_STATUS') {
    for (var filterIdx in filterObj.filterObjs) {
        if (filterIdx != undefined && filterObj.filterObjs[filterIdx].id == 'SMR_STATUS') break;
    }
    var comboObj = filterObj.filterObjs[filterIdx];
    var optionList = ['ALL', 'T']; // ALL 전체, T 임시저장
    if (sUtils.workflow.check('USW1635987860041') || sUtils.workflow.check('CSW1635988016443')) optionList.push('I', 'R'); // 결재모듈
    if (sUtils.workflow.check('CSW1635988016964')) optionList.push('G', 'N'); // 법무팀 승인
    if (sUtils.workflow.check('USW1637309480717')) optionList.push('W', 'F'); // 인감관리자 승인
    if (sUtils.workflow.check('USW1687397809419')) optionList.push('DR', 'DC', 'DW'); // 검수신청
    if (sUtils.workflow.check('USW1635987861018') || sUtils.workflow.check('CSW1635988019236')) optionList.push('CR', 'CE', 'C'); // 완료

    for (var i = 0; i < comboObj.comboList.length; i++) {
        if (optionList.indexOf(comboObj.comboList[i].comboValue) == -1) {
            comboObj.comboList.splice(i, 1);
            comboObj.comboListModal.getElementsByClassName('status_combo_list_item')[i].remove();
            --i;
        }
    }
}


//현대중공업 현황통합화면(인감날인신청+증명서발급신청)
dataOutput.setValue("APPLY_TYPE", "C,U,D");
dataOutput.setValue('MODE', 'LIST', true);
dataOutput.setValue('SHOW_REAL_ATTACH_STATUS', 'true', true);
if (Sepoa.info.MASTER_COMPANY_FLAG != 'Y' && Sepoa.info.MENU_PROFILE_CODE == Sepoa.config.get('sepoa.system.manager.profile.code')) { // Master Admin 일 경우
	dataOutput.setValue('COMPANY_CODE', '', true);
}
dataOutput.addFilter(filterObj);
gridObj.postConnection(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doQuery', 'METHOD=doSelectRequestList', 'PROCESS_ID=sepoa.svc.seal.SepoaReqSealService']);
gridObj.clearAll(false);


var header = gridObj.getColumnId(ind);
let coverProgress = false; // 더블클릭 방지용 프로그레스 모달을 켰는지
var selected = gridObj.cells(id, gridObj.getColIndexById("SELECTED")).getValue();
if (selected == 0) {
    gridObj.cells(id, gridObj.getColIndexById("SELECTED")).setValue(1);
} else {
    gridObj.cells(id, gridObj.getColIndexById("SELECTED")).setValue(0);
}
if (header == 'REAL_ATTACH_IMG') {
    var width = 568;
    var height = 500;
    var status = gridObj.cells(id, gridObj.getColIndexById('REAL_ATTACH_STATUS')).getValue();
    if (status == 'D' || status == 'N') {
        PopupOpenPost(
            'RealAttachPopup.sux', {
                SMR_NUMBER: gridObj.cells(id, gridObj.getColIndexById('SMR_NUMBER')).getValue(),
                ROW_ID: id,
                MODE: 'VI'
            },
            null,
            width,
            height,
            Sepoa.cache.text.get('SLM_203.TITLE')
        );
    }
} else if (['SUBJECT'].indexOf(header) > -1) {
    const smrStatus = gridObj.cells(id, gridObj.getColIndexById('SMR_STATUS')).getValue();
    if (smrStatus == 'T') return;
    sUtils.progress.on();
    coverProgress = true;
    doSearch(id);
}

if (coverProgress) {
    setTimeout(function() {
        sUtils.progress.off();
    }, 100);
}


var mode = obj.mode;
var status = obj.status;
var message = obj.message;
if (status == 'true') {
    Alert(message);
    doQuery();
} else {
    Alert(message);
}


for (var i = 0; i < count; i++) {
    // REAL_ATTACH_STATUS (실물날인서류 상태)
    // D: DONE
    // N: NOT DONE
    // I: INVALID (전자인감이거나 상태가 완료가 아님)
    if (gridObj.cells2(i, gridObj.getColIndexById('REAL_ATTACH_STATUS')).getValue() == 'D') {
        gridObj.cells2(i, gridObj.getColIndexById('REAL_ATTACH_IMG')).setIcon('ATTACH_IMG2');
        gridObj.cells2(i, gridObj.getColIndexById('REAL_ATTACH_IMG')).cell.children[0].style = 'filter:none';
    } else if (gridObj.cells2(i, gridObj.getColIndexById('REAL_ATTACH_STATUS')).getValue() == 'N') {
        gridObj.cells2(i, gridObj.getColIndexById('REAL_ATTACH_IMG')).setIcon('ATTACH_IMG');
    }
}
